"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["78491"],{4743(e){e.exports=JSON.parse('{"id":"F493","slug":"conflict-of-interest-cost","name":"Conflicted Advice: Long-Run Cost of a Hidden Commission","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Ethics, fiduciary standards and conflicts of interest","level":"Beginner","aliases":["ethics, fiduciary standards and conflicts of interest","fiduciary vs suitability","commission cost","best interest standard"],"formula":{"latex":"C=V_{0}\\\\left[(1+r-f)^{n}-(1+r-f-c)^{n}\\\\right]","also":[],"text":"Value with a fiduciary adviser who charges f = V0 x (1 + r - f)^n; Value with a product that also pays the adviser a yearly commission c = V0 x (1 + r - f - c)^n; Cost of the conflict = difference between the two; Share of ending value lost = 1 - (1 + r - f - c)^n / (1 + r - f)^n"},"symbols":[{"symbol":"V_0","meaning":"Amount invested","unit":"money"},{"symbol":"r","meaning":"Return before costs","unit":"per year"},{"symbol":"f","meaning":"Cost of the cleaner product","unit":"per year"},{"symbol":"c","meaning":"Extra yearly commission or fee paid to the adviser","unit":"per year"},{"symbol":"n","meaning":"Years","unit":"years"}],"when_to_use":"Use it to see why fiduciary duty (acting in the client\'s best interest) matters. A suitability standard allows an adviser to sell a product that is suitable but pays them more. A one-percentage-point difference in yearly cost looks small but compounds into a large share of the final amount over many years.","worked_example":{"problem":"A client invests 100,000 for 20 years at 7% before costs. A low-cost fund charges 0.25%. A product recommended by a commission-paid adviser charges an extra 1.00% a year.","inputs":{"v":100000,"r":7,"f":0.25,"c":1,"n":20},"steps":[{"label":"Ending value, low-cost product","working":"100000 x (1+0.07-0.0025)^20","value":"369,281.60"},{"label":"Ending value, commission product","working":"100000 x (1+0.07-0.0025-0.01)^20","value":"305,919.75"},{"label":"Cost of the conflict","working":"369282-305920","value":"63,361.85"},{"label":"Share of ending value lost","working":"63361.9 / 369282","value":"17.2%"},{"label":"Cost as a multiple of the amount invested","working":"63361.9 / 100000","value":"0.63"}],"answer":"The low-cost fund grows to 369,281.60 and the commission product to 305,919.75, so the conflict costs the client 63,361.85, or 17.2% of what they would have had. That is 0.63 times the amount they invested in the first place that they gave up."},"calculator":{"available":true,"inputs":[{"id":"v","label":"Amount invested","unit":"money","type":"number","default":100000,"hint":""},{"id":"r","label":"Return before costs","unit":"%","type":"number","default":7,"hint":""},{"id":"f","label":"Cost of the cleaner product","unit":"%","type":"number","default":0.25,"hint":""},{"id":"c","label":"Extra yearly commission","unit":"%","type":"number","default":1,"hint":""},{"id":"n","label":"Years","unit":"years","type":"number","default":20,"hint":"","min":1}],"checks":[{"expr":"v>0 and n>0","message":"Amount and years must be above zero."}],"steps":[{"id":"a","label":"Ending value, low-cost product","expr":"v*(1+r-f)^n","format":"money"},{"id":"b","label":"Ending value, commission product","expr":"v*(1+r-f-c)^n","format":"money"},{"id":"cost","label":"Cost of the conflict","expr":"a-b","format":"money"},{"id":"pct","label":"Share of ending value lost","expr":"cost/a","format":"pct1"},{"id":"mult","label":"Cost as a multiple of the amount invested","expr":"cost/v","format":"num2"}],"results":["a","b","cost","pct"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"a":369281.60434829775,"b":305919.7537011467,"cost":63361.85064715106,"pct":0.17158138911081433,"mult":0.6336185064715106}},"finder":{"finds":"What a conflict of interest costs over time","needs":"Amount, return, costs, years"},"related":[{"slug":"fee-drag","name":"Cost of Fees: Active vs. Passive"},{"slug":"fv-lump-sum","name":"Future Value of a Lump Sum"},{"slug":"mental-accounting-cost","name":"Mental Accounting: Cost of Separate Pots"}],"related_ids":["F244","F011","F425"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>C</mi><mo>=</mo><msub><mi>V</mi><mn>0</mn></msub><mrow><mo fence=\\"true\\">[</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mo>\u2212</mo><mi>f</mi><msup><mo stretchy=\\"false\\">)</mo><mi>n</mi></msup><mo>\u2212</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>r</mi><mo>\u2212</mo><mi>f</mi><mo>\u2212</mo><mi>c</mi><msup><mo stretchy=\\"false\\">)</mo><mi>n</mi></msup><mo fence=\\"true\\">]</mo></mrow></mrow><annotation encoding=\\"application/x-tex\\">C=V_{0}\\\\left[(1+r-f)^{n}-(1+r-f-c)^{n}\\\\right]</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"confidence-interval-mean","name":"Confidence Interval for a Mean"},"next":{"slug":"laspeyres-cpi","name":"Consumer Price Index (Laspeyres) and Substitution Bias"},"lesson":null,"total":522}')}}]);